import{_ as t,C as e,c as a,o as i,j as s,b as r,a0 as o,a as l,w as n,G as d,a1 as h}from"./chunks/framework.DKRgXLPU.js";const u=JSON.parse('{"title":"Creating Your Training Plan","description":"","frontmatter":{},"headers":[],"relativePath":"en/education/goals/planning.md","filePath":"en/education/goals/planning.md"}');const c=t({name:"en/education/goals/planning.md"},[["render",function(t,u,c,p,g,m){const y=e("Mermaid");return i(),a("div",null,[u[1]||(u[1]=s("h1",{id:"creating-your-training-plan",tabindex:"-1"},[l("Creating Your Training Plan "),s("a",{class:"header-anchor",href:"#creating-your-training-plan","aria-label":'Permalink to "Creating Your Training Plan"'},"​")],-1)),u[2]||(u[2]=s("p",null,"Goals without a plan are just wishes. This guide helps you turn your goals into a structured training plan that actually works.",-1)),u[3]||(u[3]=s("div",{class:"tip custom-block"},[s("p",{class:"custom-block-title"},"The Big Idea"),s("p",null,[s("strong",null,"Goals without a plan are just wishes."),l(" A structured training plan transforms your goals into daily actions that compound into real progress.")])],-1)),(i(),r(h,null,{default:n(()=>[d(y,{id:"mermaid-11",class:"mermaid",graph:"graph%20TD%0A%20%20%20%20A%5BGoal%5D%20--%3E%20B%5BTraining%20Plan%5D%0A%20%20%20%20B%20--%3E%20C%5BDaily%20Actions%5D%0A%20%20%20%20C%20--%3E%20D%5BConsistent%20Practice%5D%0A%20%20%20%20D%20--%3E%20E%5BMeasurable%20Progress%5D%0A%20%20%20%20E%20--%3E%20F%5BGoal%20Achievement%5D%0A%0A%20%20%20%20style%20A%20fill%3A%23e3f2fd%0A%20%20%20%20style%20B%20fill%3A%23e8f5e9%0A%20%20%20%20style%20C%20fill%3A%23fff4e1%0A%20%20%20%20style%20F%20fill%3A%23fff4e1%0A"})]),fallback:n(()=>[...u[0]||(u[0]=[l(" Loading... ",-1)])]),_:1})),u[4]||(u[4]=o('<h2 id="the-8-phases-of-self-directed-development" tabindex="-1">The 8 Phases of Self-Directed Development <a class="header-anchor" href="#the-8-phases-of-self-directed-development" aria-label="Permalink to &quot;The 8 Phases of Self-Directed Development&quot;">​</a></h2><h3 id="phase-1-set-your-compass-goals" tabindex="-1">Phase 1: Set Your Compass (Goals) <a class="header-anchor" href="#phase-1-set-your-compass-goals" aria-label="Permalink to &quot;Phase 1: Set Your Compass (Goals)&quot;">​</a></h3><p>You&#39;ve already learned about SMART goals. Now put them in a hierarchy:</p><ol><li><strong>Long-term goal</strong> (1-2 years): Your dream</li><li><strong>Annual goal</strong>: This year&#39;s target</li><li><strong>Quarterly goals</strong>: 3-month milestones</li><li><strong>Monthly goals</strong>: Specific focus areas</li><li><strong>Weekly goals</strong>: Training targets</li></ol><h3 id="phase-2-assess-your-resources" tabindex="-1">Phase 2: Assess Your Resources <a class="header-anchor" href="#phase-2-assess-your-resources" aria-label="Permalink to &quot;Phase 2: Assess Your Resources&quot;">​</a></h3><p>Before planning, honestly evaluate what you have:</p><table tabindex="0"><thead><tr><th>Resource</th><th>Questions to Ask</th></tr></thead><tbody><tr><td><strong>Time</strong></td><td>How many hours per week can you realistically train?</td></tr><tr><td><strong>Location</strong></td><td>Do you have access to a proper piste? What&#39;s the surface quality?</td></tr><tr><td><strong>Equipment</strong></td><td>Do you have appropriate boules? Measuring tools? Video capability?</td></tr><tr><td><strong>Knowledge</strong></td><td>What are your technical strengths and weaknesses?</td></tr><tr><td><strong>Physical condition</strong></td><td>Any limitations? Areas needing work?</td></tr></tbody></table><p>Be honest. A realistic plan beats an ambitious fantasy.</p><h3 id="phase-3-choose-your-exercises" tabindex="-1">Phase 3: Choose Your Exercises <a class="header-anchor" href="#phase-3-choose-your-exercises" aria-label="Permalink to &quot;Phase 3: Choose Your Exercises&quot;">​</a></h3><p>Select exercises that directly support your goals:</p><p><strong>For pointing improvement:</strong></p><ul><li>Precision pointing to marked zones</li><li>Distance variation drills</li><li>Different surface practice</li></ul><p><strong>For shooting improvement:</strong></p><ul><li>Shooting ladder (progressive distances)</li><li>Obstacle shooting (forced high arc)</li><li>Moving target practice</li></ul><p><strong>For mental development:</strong></p><ul><li>Pre-shot routine practice</li><li>Visualization sessions</li><li>Pressure simulation</li></ul><p><strong>Balance your program:</strong></p><ul><li>Technical work (pointing, shooting)</li><li>Mental training (mindfulness, visualization)</li><li>Physical conditioning (balance, flexibility)</li><li>Match play (applying skills)</li></ul><h3 id="phase-4-create-your-schedule" tabindex="-1">Phase 4: Create Your Schedule <a class="header-anchor" href="#phase-4-create-your-schedule" aria-label="Permalink to &quot;Phase 4: Create Your Schedule&quot;">​</a></h3><p>Build a realistic weekly schedule:</p><table tabindex="0"><thead><tr><th>Day</th><th>Morning</th><th>Afternoon</th><th>Evening</th><th>Focus</th></tr></thead><tbody><tr><td>Mon</td><td>-</td><td>Technical: Pointing</td><td>Light mobility</td><td>Precision</td></tr><tr><td>Tue</td><td>-</td><td>Technical: Shooting</td><td>-</td><td>Power/accuracy</td></tr><tr><td>Wed</td><td>-</td><td>Mental training</td><td>-</td><td>Mindfulness</td></tr><tr><td>Thu</td><td>-</td><td>Mixed: Game scenarios</td><td>Light mobility</td><td>Application</td></tr><tr><td>Fri</td><td>-</td><td>Technical: Weakness</td><td>-</td><td>Improvement</td></tr><tr><td>Sat</td><td>Match play or competition</td><td>-</td><td>-</td><td>Performance</td></tr><tr><td>Sun</td><td>Rest</td><td>Weekly review</td><td>Planning</td><td>Recovery</td></tr></tbody></table><p><strong>Key principles:</strong></p><ul><li>Prioritize mental training (it&#39;s often neglected)</li><li>Include rest days</li><li>Balance different skills</li><li>Leave flexibility for life</li></ul><h3 id="phase-5-prepare-for-obstacles" tabindex="-1">Phase 5: Prepare for Obstacles <a class="header-anchor" href="#phase-5-prepare-for-obstacles" aria-label="Permalink to &quot;Phase 5: Prepare for Obstacles&quot;">​</a></h3><p>Things will go wrong. Plan for it.</p><table tabindex="0"><thead><tr><th>Risk</th><th>Likelihood</th><th>Impact</th><th>Backup Plan</th></tr></thead><tbody><tr><td>Time shortage</td><td>High</td><td>Medium</td><td>Have a &quot;minimum session&quot; ready (20 min)</td></tr><tr><td>Bad weather</td><td>Medium</td><td>Medium</td><td>Indoor visualization, video study</td></tr><tr><td>Low motivation</td><td>High</td><td>Medium</td><td>Return to &quot;why&quot;, smaller goals, take a break</td></tr><tr><td>Minor injury</td><td>Medium</td><td>High</td><td>Focus on mental training, non-affected skills</td></tr><tr><td>No practice partner</td><td>Medium</td><td>Low</td><td>Solo drills, video self-analysis</td></tr></tbody></table><h3 id="phase-6-track-your-progress" tabindex="-1">Phase 6: Track Your Progress <a class="header-anchor" href="#phase-6-track-your-progress" aria-label="Permalink to &quot;Phase 6: Track Your Progress&quot;">​</a></h3><p>What gets measured gets managed.</p><p><strong>Keep a training diary:</strong></p><ul><li>Date and duration</li><li>Exercises completed</li><li>Scores/results</li><li>How you felt (energy, focus, flow)</li><li>Technical notes</li><li>Weather/conditions</li></ul><p><strong>Weekly review questions:</strong></p><ul><li>Did I complete my planned sessions?</li><li>What scores did I achieve?</li><li>What felt good? What was difficult?</li><li>Any flow experiences?</li><li>What should I adjust?</li></ul><h3 id="phase-7-stay-motivated" tabindex="-1">Phase 7: Stay Motivated <a class="header-anchor" href="#phase-7-stay-motivated" aria-label="Permalink to &quot;Phase 7: Stay Motivated&quot;">​</a></h3><p>Motivation fluctuates. Build systems to maintain it:</p><p><strong>Internal motivation:</strong></p><ul><li>Connect to your &quot;why&quot;</li><li>Celebrate small wins</li><li>Notice improvement over time</li><li>Find joy in the process</li></ul><p><strong>External support:</strong></p><ul><li>Training partners (even occasionally)</li><li>Share goals with someone</li><li>Join online communities</li><li>Track streaks and consistency</li></ul><p><strong>When motivation drops:</strong></p><ul><li>Do a minimum session (something beats nothing)</li><li>Change your environment</li><li>Review your progress</li><li>Remember past successes</li><li>Take a planned break if needed</li></ul><h3 id="phase-8-review-and-adapt" tabindex="-1">Phase 8: Review and Adapt <a class="header-anchor" href="#phase-8-review-and-adapt" aria-label="Permalink to &quot;Phase 8: Review and Adapt&quot;">​</a></h3><p>Your plan should evolve:</p><p><strong>Weekly:</strong> Quick review, minor adjustments <strong>Monthly:</strong> Assess progress toward monthly goals, adjust focus <strong>Quarterly:</strong> Major review, set next quarter&#39;s goals <strong>Annually:</strong> Full assessment, new annual plan</p><p><strong>Questions for review:</strong></p><ul><li>Am I making progress toward my goals?</li><li>Is my training effective?</li><li>Do I need different exercises?</li><li>Are my goals still relevant?</li><li>What have I learned?</li></ul><h2 id="sample-8-week-plan" tabindex="-1">Sample 8-Week Plan <a class="header-anchor" href="#sample-8-week-plan" aria-label="Permalink to &quot;Sample 8-Week Plan&quot;">​</a></h2><p><strong>Goal:</strong> Improve shooting accuracy by 15%</p><table tabindex="0"><thead><tr><th>Week</th><th>Focus</th><th>Key Sessions</th></tr></thead><tbody><tr><td>1</td><td>Baseline</td><td>Test current level, video analysis</td></tr><tr><td>2</td><td>Technique</td><td>Identify and work on key issue</td></tr><tr><td>3</td><td>Repetition</td><td>High volume shooting practice</td></tr><tr><td>4</td><td>Test</td><td>Mid-point assessment, adjust</td></tr><tr><td>5</td><td>Variation</td><td>Different distances and angles</td></tr><tr><td>6</td><td>Pressure</td><td>Add consequences to drills</td></tr><tr><td>7</td><td>Integration</td><td>Game-like scenarios</td></tr><tr><td>8</td><td>Final test</td><td>Measure improvement</td></tr></tbody></table><h2 id="key-takeaway" tabindex="-1">Key Takeaway <a class="header-anchor" href="#key-takeaway" aria-label="Permalink to &quot;Key Takeaway&quot;">​</a></h2><blockquote><p>Plan your work, then work your plan. But be ready to adapt.</p></blockquote><p>The best plan is one you&#39;ll actually follow. Start simple, stay consistent, and adjust as you learn.</p>',51))])}]]);export{u as __pageData,c as default};
